 static PGSimpleDataSource runtime,migrator;static DataSource tracked;static UUID tenant,actor=UUID.randomUUID();static BackupEnvelopeEncryption crypto;
 static final String REF="sha256:"+"a".repeat(64),BAD="sha256:"+"b".repeat(64);
 static final AtomicInteger checks=new AtomicInteger(),open=new AtomicInteger(),objectChecks=new AtomicInteger(),completionChecks=new AtomicInteger();static final ThreadLocal<Integer> threadOpen=ThreadLocal.withInitial(()->0);
 static final Map<UUID,byte[]> objects=new ConcurrentHashMap<>();static final AtomicBoolean revoked=new AtomicBoolean(),metadataVisibleBeforeFailure=new AtomicBoolean();
