  check(!receipt.replay()&&receipt.registration().completedRunVersion()==2&&receipt.registration().registrationAndRunCompletionRecorded(),"metadata_and_matching_success_committed");
  check(!receipt.registration().currentObjectHealthVerified()&&!receipt.registration().deviceExecutionAuthorized()&&!receipt.registration().retentionVerified()&&!receipt.registration().recoveryVerified(),"historical_registration_not_health_retention_recovery_or_execution_authority");
  var current=runs().current(tenant,f.scope().assetId(),f.scope().runId()).orElseThrow();check(current.state().state()==BackupRunState.State.SUCCEEDED&&current.recordedAt().equals(receipt.registration().registeredAt()),"same_transaction_timestamp_and_parent_success");check(current.state().attempts().get(0).storedVersion().persistedAt().equals(f.observed()),"known_present_observation_not_invented_cloud_creation_time");
  check(count("mop_backup_archive_event",f.scope().versionId())==archiveCount&&Arrays.equals(archive().current(archiveAccess(),f.scope()).orElseThrow().source().payload().bytes(),f.payload().bytes()),"original_archive_facts_and_ciphertext_unchanged");check(leases().current(tenant,f.scope().assetId(),f.lease().requestId()).orElseThrow().state().releasedAt()==null,"version_registration_does_not_release_device_lease");
