  revoked.set(true);denied(()->register(repository,f,command,1,REF,REF),"revoked_actor_cannot_replay");denied(()->repository.current(access(),f.scope()),"revoked_actor_cannot_read");revoked.set(false);
  denied(()->repository.current(new Access(id(),actor,1),f.scope()),"cross_tenant_hidden");
  Fixture badObject=fixture();objects.remove(badObject.scope().versionId());unavailable(()->register(repository,badObject,id(),1,REF,REF),"missing_original_object_cannot_register");check(count("mop_backup_version_registration",badObject.scope().versionId())==0&&runs().current(tenant,badObject.scope().assetId(),badObject.scope().runId()).orElseThrow().state().version()==1,"object_failure_no_metadata_or_success");
  Fixture badCompletion=fixture();unavailable(()->register(repository,badCompletion,id(),1,REF,BAD),"object_authentication_does_not_replace_execution_completion_proof");check(count("mop_backup_version_registration",badCompletion.scope().versionId())==0&&runs().current(tenant,badCompletion.scope().assetId(),badCompletion.scope().runId()).orElseThrow().state().version()==1,"completion_veto_rolls_back_all_registration_work");
  Fixture rollback=fixture();UUID rollbackCommand=id();faultVersion=rollback.scope().versionId();fault=Fault.REJECT_RUN_INSERT;denied(()->register(repository,rollback,rollbackCommand,1,REF,REF),"injected_parent_insert_failure_rejected");fault=Fault.NONE;check(metadataVisibleBeforeFailure.get()&&count("mop_backup_version_registration",rollback.scope().versionId())==0&&runs().current(tenant,rollback.scope().assetId(),rollback.scope().runId()).orElseThrow().state().version()==1,"metadata_insert_then_parent_failure_rolls_back_both");check(!register(repository,rollback,rollbackCommand,1,REF,REF).replay(),"same_command_can_complete_after_confirmed_rollback_without_new_version");
  Fixture lost=fixture();UUID lostCommand=id();fault=Fault.LOSE_COMMIT_REPLY;unavailable(()->register(repository,lost,lostCommand,1,REF,REF),"lost_commit_response_reported_unconfirmed");fault=Fault.NONE;proofs=objectChecks.get();check(repository.current(access(),lost.scope()).orElseThrow().registration().completedRunVersion()==2,"readonly_recovery_finds_both_committed_facts");check(register(repository,lost,lostCommand,1,REF,REF).replay()&&objectChecks.get()==proofs&&count("mop_backup_version_registration",lost.scope().versionId())==1,"lost_response_original_replay_no_duplicate_version_or_object_call");
  Fixture orphan=fixture();denied(()->{try(var c=runtime.getConnection()){c.setAutoCommit(false);rawRegistrationOnly(c,orphan);c.commit();}},"deferred_constraint_rejects_metadata_without_success");check(count("mop_backup_version_registration",orphan.scope().versionId())==0,"metadata_only_transaction_does_not_persist");
