  Fixture race=fixture();var changeDuringProof=new PostgresBackupVersionRepository(tracked,BackupVersionPostgresTest::authorize,(a,c,r)->{verifyObject(a,c,r);runs().markUnknown(tenant,race.scope().assetId(),race.scope().runId(),id(),1,race.lease(),"racing_unknown");},BackupVersionPostgresTest::verifyCompletion);denied(()->register(changeDuringProof,race,id(),1,REF,REF),"new_parent_state_during_object_recheck_cannot_be_overwritten");check(count("mop_backup_version_registration",race.scope().versionId())==0,"stale_proof_keeps_newer_unknown_parent");check(register(repository,race,id(),2,REF,REF).registration().completedRunVersion()==3,"explicit_current_unknown_resolution_requires_fresh_proof_and_version");
  Fixture concurrent=fixture();var pool=Executors.newFixedThreadPool(2);var latch=new CountDownLatch(1);try{var jobs=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{latch.await();try{register(repo(),concurrent,id(),1,REF,REF);return true;}catch(DomainException e){if(e.status!=409)throw e;return false;}}));latch.countDown();int wins=0;for(var job:jobs)if(job.get(20,TimeUnit.SECONDS))wins++;check(wins==1&&count("mop_backup_version_registration",concurrent.scope().versionId())==1,"concurrent_distinct_commands_exactly_one_atomic_winner");}finally{pool.shutdownNow();}
  Fixture same=fixture();UUID sameCommand=id();var samePool=Executors.newFixedThreadPool(2);var sameLatch=new CountDownLatch(1);try{var jobs=new ArrayList<Future<Receipt>>();for(int i=0;i<2;i++)jobs.add(samePool.submit(()->{sameLatch.await();return register(repo(),same,sameCommand,1,REF,REF);}));sameLatch.countDown();int replayed=0;for(var job:jobs)if(job.get(20,TimeUnit.SECONDS).replay())replayed++;check(replayed==1&&count("mop_backup_version_registration",same.scope().versionId())==1,"concurrent_identical_command_one_commit_one_original_replay");}finally{samePool.shutdownNow();}
